package vn.covie.inventory.application;
import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import vn.covie.auth.security.CurrentActorProvider; import vn.covie.inventory.api.dto.*; import vn.covie.shared.web.*;
@Service public class InventoryBulkService{private final CurrentActorProvider actors;private final InventoryBulkItemExecutor items;public InventoryBulkService(CurrentActorProvider actors,InventoryBulkItemExecutor items){this.actors=actors;this.items=items;}public BulkSetStockResult setStock(UUID merchantId,String key,BulkSetStockRequest request){if(key==null||key.isBlank())throw new ApiException(ErrorCode.IDEMPOTENCY_KEY_REQUIRED,HttpStatus.BAD_REQUEST,"Idempotency-Key is required.");if(request==null||request.items()==null||request.items().isEmpty()||request.items().size()>100)throw new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,"Bulk request must contain 1 to 100 items.");Set<UUID> ids=new HashSet<>();if(request.items().stream().anyMatch(i->i==null||i.locationVariantId()==null||i.stockOnHand()<0||!ids.add(i.locationVariantId())))throw new ApiException(ErrorCode.VALIDATION_FAILED,HttpStatus.UNPROCESSABLE_ENTITY,"Bulk items must be unique and non-negative.");UUID actor=actors.currentActor().userId();return new BulkSetStockResult(request.items().stream().map(i->items.execute(actor,merchantId,i,request.reasonCode(),request.note(),key)).toList());}}
